<template><PageContainer title="最近对话" description="继续、搜索和管理所有 Agent 会话。"><template #extra><el-button type="primary" @click="newSession"><AppIcon name="Plus" />新对话</el-button></template><div class="history-tools"><el-input v-model="query" clearable placeholder="搜索对话标题" @input="load"><template #prefix><AppIcon name="Search" /></template></el-input></div><el-table :data="sessions" v-loading="loading" empty-text="开始你的第一个对话"><el-table-column prop="title" label="标题" min-width="220"/><el-table-column prop="projectName" label="项目" min-width="130"><template #default="{row}">{{row.projectName||'临时对话'}}</template></el-table-column><el-table-column prop="modelId" label="模型" min-width="130"><template #default="{row}">{{row.modelId||'默认模型'}}</template></el-table-column><el-table-column prop="status" label="状态" width="100"><template #default="{row}"><el-tag size="small" :type="row.status==='failed'?'danger':row.status==='active'?'warning':'success'">{{row.status==='active'?'进行中':row.status==='failed'?'失败':'完成'}}</el-tag></template></el-table-column><el-table-column label="时间" width="120"><template #default="{row}">{{formatTime(row.updatedAt)}}</template></el-table-column><el-table-column label="操作" width="130"><template #default="{row}"><el-button link type="primary" @click="open(row.id)">打开</el-button><el-button link type="danger" @click="remove(row.id)">删除</el-button></template></el-table-column></el-table><el-empty v-if="!loading&&!sessions.length" description="开始你的第一个对话"><el-button type="primary" @click="newSession">新对话</el-button></el-empty></PageContainer></template>
<script setup lang="ts">import { onMounted,ref } from 'vue';import { useRouter } from 'vue-router';import { ElMessageBox } from 'element-plus';import { getPlatformApi } from '@/platform';import type { HarnessSessionSummary } from '@/config/harness';import PageContainer from '@/components/PageContainer/index.vue';import { useHarnessStore } from '@/stores/harness';const router=useRouter(),store=useHarnessStore(),sessions=ref<HarnessSessionSummary[]>([]),query=ref(''),loading=ref(false);async function load(){loading.value=true;try{sessions.value=await getPlatformApi()?.listHarnessSessions(query.value)||[]}finally{loading.value=false}}async function newSession(){const draft=store.startDraft();void router.push({path:'/workspace/chat',query:{draft}})}function open(id:string){void router.push(`/workspace/chat/${id}`)}async function remove(id:string){await ElMessageBox.confirm('删除后无法恢复该会话。','删除会话',{type:'warning'});await getPlatformApi()?.deleteHarnessSession(id);await load()}function formatTime(value:number){return new Intl.RelativeTimeFormat('zh-CN',{numeric:'auto'}).format(Math.round((value-Date.now())/3600000),'hour')};onMounted(load);</script>
<style scoped lang="scss">.history-tools{width:min(100%,360px);margin-bottom:$spacing-lg}</style>
